import {
  AlertCircle,
  CheckCircle2,
  FileCode2,
  HardDrive,
  Link2,
  LoaderCircle,
  Scale,
  Trash2,
  Upload
} from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { compareBuilds, importPob, isPobXml, type BuildSnapshot, type ComparisonReport } from "@poe-odyssey/core";
import { PageTitle } from "../App";
import { bridgeCompare, bridgeDecode, type BridgeComparison } from "../bridgeClient";
import { rfChieftainGuide, stageForLevel } from "../content/rfChieftain";
import { clearBuilds, removeBuild, saveBuild, savedBuilds } from "../storage";

const allowedImportHosts = new Set(["pobb.in", "poe.ninja", "poedb.tw"]);

async function resolveInput(value: string): Promise<string> {
  const trimmed = value.trim();
  if (!/^https?:\/\//i.test(trimmed)) return trimmed;
  const url = new URL(trimmed);
  if (!allowedImportHosts.has(url.hostname)) throw new Error("只接受 pobb.in、poe.ninja PoB 與 PoEDB 連結。");
  if (url.hostname === "poe.ninja" && url.pathname.includes("/character/")) {
    throw new Error("不爬取 poe.ninja 角色頁；請在角色頁複製 PoB 分享碼後貼入。");
  }
  const requestUrl = url.hostname === "pobb.in" && !url.pathname.endsWith("/raw")
    ? new URL(`${url.pathname.replace(/\/$/, "")}/raw`, url.origin)
    : url.hostname === "poe.ninja"
      ? new URL(url.pathname.replace(/\/poe1\/pob\/([^/]+)\/?$/, "/poe1/pob/raw/$1"), url.origin)
      : url;
  const response = await fetch(requestUrl, { headers: { Accept: "text/plain, application/xml" } });
  if (!response.ok) throw new Error(`外部 PoB 讀取失敗（${response.status}）；請改貼分享碼。`);
  const length = Number(response.headers.get("content-length") ?? 0);
  if (length > 8 * 1024 * 1024) throw new Error("遠端 PoB 超過 8 MB。");
  const text = await response.text();
  if (text.length > 8 * 1024 * 1024) throw new Error("遠端 PoB 超過 8 MB。");
  return text.trim();
}

function BuildCard({
  build,
  selected,
  select,
  remove
}: {
  build: BuildSnapshot;
  selected: boolean;
  select: () => void;
  remove: () => void;
}) {
  return (
    <article className={`saved-build ${selected ? "selected" : ""}`} onClick={select}>
      <div className="build-radio"><span /></div>
      <div>
        <strong>{build.name}</strong>
        <small>{build.character.ascendancy ?? build.character.className ?? "Unknown"} · Lv {build.character.level}</small>
        <p>{build.items.length} 裝備 · {build.skills.length} 技能組 · {build.passiveNodeIds.length} 天賦</p>
      </div>
      <button className="icon-button" onClick={(event) => { event.stopPropagation(); remove(); }} aria-label="刪除 PoB">
        <Trash2 size={16} />
      </button>
    </article>
  );
}

function Report({ report }: { report: ComparisonReport }) {
  const changed = report.equipment.filter((item) => item.changed);
  return (
    <div className="report-grid">
      <section className="panel">
        <h3>裝備差異 <small>EQUIPMENT</small></h3>
        {changed.length === 0 ? <p className="empty-note">裝備文字內容相同。</p> : (
          <div className="diff-list">{changed.map((item) => (
            <div key={item.slot}>
              <strong>{item.slot}</strong>
              <span>{item.source ?? "—"} <b>→</b> {item.target ?? "—"}</span>
            </div>
          ))}</div>
        )}
      </section>
      <section className="panel">
        <h3>技能差距 <small>SKILLS</small></h3>
        <div className="diff-columns">
          <div><small>缺少</small>{report.skills.missing.map((item) => <span key={item}>+ {item}</span>)}</div>
          <div><small>多出</small>{report.skills.extra.map((item) => <span key={item}>− {item}</span>)}</div>
        </div>
      </section>
      <section className="panel">
        <h3>天賦完整目標 <small>PASSIVES</small></h3>
        <div className="big-metric">{report.passives.targetGap}<small>個目標節點尚缺</small></div>
        <p className="node-preview">{report.passives.missingNodeIds.slice(0, 18).join(", ") || "結構相同"}</p>
      </section>
      <section className="panel">
        <h3>比較限制 <small>NOTES</small></h3>
        {report.warnings.map((warning) => <p className="report-warning" key={warning}><AlertCircle size={14} />{warning}</p>)}
      </section>
    </div>
  );
}

export function ImportPage() {
  const [input, setInput] = useState("");
  const [name, setName] = useState("");
  const [builds, setBuilds] = useState<BuildSnapshot[]>([]);
  const [sourceId, setSourceId] = useState("");
  const [targetId, setTargetId] = useState("");
  const [message, setMessage] = useState<{ kind: "ok" | "error"; text: string } | null>(null);
  const [busy, setBusy] = useState(false);
  const [bridgeBusy, setBridgeBusy] = useState(false);
  const [bridgeReport, setBridgeReport] = useState<BridgeComparison | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  const refresh = useCallback(async () => setBuilds((await savedBuilds()).sort((a, b) => b.importedAt.localeCompare(a.importedAt))), []);
  useEffect(() => { void refresh(); }, [refresh]);

  const source = builds.find((build) => build.id === sourceId);
  const target = builds.find((build) => build.id === targetId);
  const stage = source ? stageForLevel(source.character.level) : rfChieftainGuide.stages[0]!;
  const report = useMemo(() => source && target ? compareBuilds(source, target, stage.id) : null, [source, target, stage.id]);

  const doImport = async () => {
    setBusy(true);
    setMessage(null);
    try {
      let snapshot: BuildSnapshot;
      try {
        const resolved = await resolveInput(input);
        snapshot = importPob(resolved, name || undefined);
      } catch (browserError) {
        if (!/^https?:\/\//i.test(input.trim())) throw browserError;
        try {
          snapshot = await bridgeDecode(input.trim(), name || undefined);
        } catch {
          throw new Error(`${browserError instanceof Error ? browserError.message : "瀏覽器無法讀取連結"} 若來源阻擋 CORS，請啟動 Bridge 或直接貼 PoB 分享碼。`);
        }
      }
      await saveBuild(snapshot);
      await refresh();
      setSourceId((current) => current || snapshot.id);
      setInput("");
      setName("");
      setMessage({ kind: "ok", text: `已匯入 ${snapshot.name}；資料只存在此瀏覽器。` });
    } catch (error) {
      setMessage({ kind: "error", text: error instanceof Error ? error.message : "無法匯入 PoB。" });
    } finally {
      setBusy(false);
    }
  };

  const readFile = async (file?: File) => {
    if (!file) return;
    if (file.size > 8 * 1024 * 1024) {
      setMessage({ kind: "error", text: "PoB 檔案超過 8 MB。" });
      return;
    }
    setInput(await file.text());
    setName(file.name.replace(/\.(xml|txt)$/i, ""));
  };

  return (
    <div className="page compare-page">
      <PageTitle
        eyebrow="LOCAL-FIRST · POB"
        title="匯入與比較 PoB"
        description="分享碼與 XML 在瀏覽器離線解析；完整 DPS／EHP 重算由本機 Bridge 執行。"
      />

      <section className="import-layout">
        <div className="panel import-panel">
          <div className="panel-title"><FileCode2 size={19} /><div><h3>新增 PoB</h3><small>IMPORT BUILD</small></div></div>
          <label className="field">
            <span>顯示名稱（選填）</span>
            <input value={name} onChange={(event) => setName(event.target.value)} placeholder="例如：我的 Lv88 RF" />
          </label>
          <label className="field">
            <span>分享碼、XML 或支援的連結</span>
            <textarea
              value={input}
              onChange={(event) => setInput(event.target.value)}
              placeholder={"貼上 PoB 分享碼、<PathOfBuilding> XML、pobb.in 或 poe.ninja/poe1/pob/{id}\n\npoe.ninja 角色頁請先複製其 PoB。"}
            />
          </label>
          <input
            ref={fileRef}
            type="file"
            accept=".xml,.txt,text/plain,application/xml"
            hidden
            onChange={(event) => void readFile(event.target.files?.[0])}
          />
          <div className="import-actions">
            <button className="button secondary" onClick={() => fileRef.current?.click()}><Upload size={16} /> 選擇檔案</button>
            <button className="button primary" disabled={!input.trim() || busy} onClick={() => void doImport()}>
              {busy ? <LoaderCircle className="spin" size={16} /> : isPobXml(input) ? <FileCode2 size={16} /> : <Link2 size={16} />}
              解析並保存
            </button>
          </div>
          {message && <div className={`form-message ${message.kind}`}>
            {message.kind === "ok" ? <CheckCircle2 size={17} /> : <AlertCircle size={17} />}{message.text}
          </div>}
          <p className="privacy-note"><HardDrive size={15} /> 不上傳伺服器；網站沒有分析帳號或雲端資料庫。</p>
        </div>

        <div className="panel library-panel">
          <div className="panel-title row-between">
            <div className="title-inner"><Scale size={19} /><div><h3>本機資料庫</h3><small>SAVED BUILDS</small></div></div>
            {builds.length > 0 && <button className="quiet-button" onClick={async () => { await clearBuilds(); setSourceId(""); setTargetId(""); await refresh(); }}>全部清除</button>}
          </div>
          {builds.length === 0 ? (
            <div className="empty-state"><FileCode2 size={30} /><strong>還沒有 PoB</strong><p>先貼入一份分享碼；再匯入參考 PoB 即可比較。</p></div>
          ) : (
            <div className="build-selection">
              <div>
                <span className="selection-label">你的角色 / SOURCE</span>
                {builds.map((build) => <BuildCard key={`source-${build.id}`} build={build} selected={sourceId === build.id} select={() => setSourceId(build.id)} remove={async () => { await removeBuild(build.id); await refresh(); }} />)}
              </div>
              <div>
                <span className="selection-label">參考目標 / TARGET</span>
                {builds.map((build) => <BuildCard key={`target-${build.id}`} build={build} selected={targetId === build.id} select={() => setTargetId(build.id)} remove={async () => { await removeBuild(build.id); await refresh(); }} />)}
              </div>
            </div>
          )}
        </div>
      </section>

      {source && (
        <div className="auto-stage">
          <span>依 Lv {source.character.level} 自動選擇</span>
          <strong>{stage.label.zhTW}</strong>
          <small>{stage.label.en}</small>
        </div>
      )}

      {report && source && target && (
        <section className="bridge-compare-bar">
          <div>
            <strong>Path of Building 完整重算</strong>
            <p>同時保留作者原始設定，並套用「{rfChieftainGuide.scenario.name.zhTW}」比較。</p>
          </div>
          <button className="button primary" disabled={bridgeBusy} onClick={async () => {
            setBridgeBusy(true);
            setMessage(null);
            try {
              setBridgeReport(await bridgeCompare(source, target, rfChieftainGuide.scenario, stage.id));
            } catch (error) {
              setMessage({ kind: "error", text: error instanceof Error ? error.message : "Bridge 重算失敗。" });
            } finally {
              setBridgeBusy(false);
            }
          }}>{bridgeBusy ? <LoaderCircle className="spin" size={16} /> : <Scale size={16} />} Bridge 重算</button>
        </section>
      )}

      {bridgeReport?.calculations && (
        <section className="calculation-grid">
          {([
            ["你的角色", bridgeReport.calculations.source],
            ["參考目標", bridgeReport.calculations.target]
          ] as const).map(([label, calculation]) => (
            <article className="panel" key={label}>
              <div className="calc-heading">
                <div><span className="eyebrow">{label}</span><h3>{calculation.engine.name}</h3></div>
                <span className={calculation.engine.complete ? "complete" : "partial"}>{calculation.engine.complete ? "完整" : "摘要"}</span>
              </div>
              <div className="calc-columns">
                <div><small>原始設定 / RAW</small>{Object.entries(calculation.raw).slice(0, 8).map(([key, value]) => <p key={key}><span>{key}</span><strong>{Math.round(value).toLocaleString()}</strong></p>)}</div>
                <div><small>標準設定 / NORMALIZED</small>{Object.entries(calculation.normalized).slice(0, 8).map(([key, value]) => <p key={key}><span>{key}</span><strong>{Math.round(value).toLocaleString()}</strong></p>)}</div>
              </div>
              {calculation.warnings.map((warning) => <p className="report-warning" key={warning}><AlertCircle size={14} />{warning}</p>)}
            </article>
          ))}
        </section>
      )}

      {bridgeReport?.slotEffects && bridgeReport.slotEffects.length > 0 && (
        <section className="panel slot-effects">
          <h3>逐槽替換效果 <small>ONE SLOT AT A TIME</small></h3>
          {bridgeReport.slotEffects.map((effect) => <div key={effect.slot}>
            <span>{effect.slot}<small>{effect.item}</small></span>
            <strong className={(effect.damageDelta ?? 0) >= 0 ? "positive" : "negative"}>傷害 {effect.damageDelta === null ? "—" : `${effect.damageDelta >= 0 ? "+" : ""}${effect.damageDelta.toFixed(1)}%`}</strong>
            <strong className={(effect.survivalDelta ?? 0) >= 0 ? "positive" : "negative"}>生存 {effect.survivalDelta === null ? "—" : `${effect.survivalDelta >= 0 ? "+" : ""}${effect.survivalDelta.toFixed(1)}%`}</strong>
          </div>)}
        </section>
      )}

      {report ? <Report report={report} /> : (
        <section className="compare-placeholder"><Scale size={28} /><div><strong>選擇兩份 PoB 開始比較</strong><p>若只有一份，可再匯入攻略或 poe.ninja 角色提供的 PoB 分享碼。</p></div></section>
      )}
    </div>
  );
}
