import type { BuildSnapshot } from "@poe-odyssey/core";
import { openDB } from "idb";

const database = openDB("poe-odyssey", 1, {
  upgrade(db) {
    if (!db.objectStoreNames.contains("builds")) {
      db.createObjectStore("builds", { keyPath: "id" });
    }
  }
});

export async function savedBuilds(): Promise<BuildSnapshot[]> {
  return (await database).getAll("builds") as Promise<BuildSnapshot[]>;
}

export async function saveBuild(snapshot: BuildSnapshot): Promise<void> {
  await (await database).put("builds", snapshot);
}

export async function removeBuild(id: string): Promise<void> {
  await (await database).delete("builds", id);
}

export async function clearBuilds(): Promise<void> {
  await (await database).clear("builds");
}
