import {
  BookOpen,
  Boxes,
  ChevronRight,
  Database,
  Download,
  Flame,
  Github,
  Languages,
  Menu,
  Scale,
  Search,
  ShieldCheck,
  ShoppingCart,
  Swords,
  X
} from "lucide-react";
import { useEffect, useMemo, useState, type ReactNode } from "react";
import { NavLink, Route, Routes } from "react-router-dom";
import { bridgeHealth } from "./bridgeClient";
import { AboutPage } from "./pages/AboutPage";
import { DownloadPage } from "./pages/DownloadPage";
import { GuidePage } from "./pages/GuidePage";
import { HomePage } from "./pages/HomePage";
import { ImportPage } from "./pages/ImportPage";
import { TradePage } from "./pages/TradePage";

const nav = [
  { to: "/", label: "總覽", en: "Overview", icon: Boxes },
  { to: "/guide/rf-chieftain", label: "開荒指南", en: "Build guide", icon: BookOpen },
  { to: "/compare", label: "PoB 比較", en: "Compare", icon: Scale },
  { to: "/trade", label: "台服市集", en: "TW Trade", icon: ShoppingCart },
  { to: "/download", label: "桌面橋接器", en: "Bridge", icon: Download },
  { to: "/about", label: "資料與授權", en: "Sources", icon: Database }
];

function Header({ onMenu }: { onMenu: () => void }) {
  const [bridge, setBridge] = useState<"checking" | "online" | "offline">("checking");
  useEffect(() => {
    void bridgeHealth().then(() => setBridge("online")).catch(() => setBridge("offline"));
  }, []);
  return (
    <header className="topbar">
      <button className="icon-button menu-button" onClick={onMenu} aria-label="開啟選單">
        <Menu size={20} />
      </button>
      <div className="league-chip"><span className="pulse-dot" /> 3.29 · Allflame</div>
      <div className="top-actions">
        <div className={`bridge-state ${bridge}`}>
          <span />
          {bridge === "online" ? "Bridge 已配對" : bridge === "checking" ? "Bridge 檢查中" : "純網頁模式"}
        </div>
        <a className="icon-button" href="https://github.com/ts03408751/PoeOdyssey" target="_blank" rel="noreferrer" aria-label="GitHub">
          <Github size={19} />
        </a>
      </div>
    </header>
  );
}

function Sidebar({ open, close }: { open: boolean; close: () => void }) {
  return (
    <>
      <div className={`mobile-scrim ${open ? "open" : ""}`} onClick={close} />
      <aside className={`sidebar ${open ? "open" : ""}`}>
        <div className="brand">
          <div className="brand-mark"><Flame size={24} strokeWidth={1.8} /></div>
          <div>
            <strong>PoeOdyssey</strong>
            <small>流亡旅程導航</small>
          </div>
          <button className="icon-button close-button" onClick={close} aria-label="關閉選單"><X size={18} /></button>
        </div>
        <nav>
          {nav.map(({ to, label, en, icon: Icon }) => (
            <NavLink key={to} to={to} end={to === "/"} onClick={close}>
              <Icon size={18} />
              <span>{label}<small>{en}</small></span>
              <ChevronRight className="nav-chevron" size={15} />
            </NavLink>
          ))}
        </nav>
        <div className="sidebar-card">
          <ShieldCheck size={20} />
          <strong>資料留在你的裝置</strong>
          <p>PoB 預設只存於瀏覽器 IndexedDB。清除與匯出都由你控制。</p>
        </div>
        <div className="sidebar-meta">
          <span>v0.1.0</span>
          <span>Unofficial</span>
        </div>
      </aside>
    </>
  );
}

export function PageTitle({
  eyebrow,
  title,
  description,
  children
}: {
  eyebrow: string;
  title: string;
  description: string;
  children?: ReactNode;
}) {
  return (
    <div className="page-title">
      <div>
        <span className="eyebrow">{eyebrow}</span>
        <h1>{title}</h1>
        <p>{description}</p>
      </div>
      {children && <div className="page-actions">{children}</div>}
    </div>
  );
}

export function StatPill({ icon, label, value }: { icon: ReactNode; label: string; value: string }) {
  return <div className="stat-pill">{icon}<span>{label}<strong>{value}</strong></span></div>;
}

export function App() {
  const [menuOpen, setMenuOpen] = useState(false);
  const shellClass = useMemo(() => menuOpen ? "app menu-open" : "app", [menuOpen]);
  return (
    <div className={shellClass}>
      <Sidebar open={menuOpen} close={() => setMenuOpen(false)} />
      <div className="main-shell">
        <Header onMenu={() => setMenuOpen(true)} />
        <main>
          <Routes>
            <Route path="/" element={<HomePage />} />
            <Route path="/guide/rf-chieftain" element={<GuidePage />} />
            <Route path="/compare" element={<ImportPage />} />
            <Route path="/trade" element={<TradePage />} />
            <Route path="/download" element={<DownloadPage />} />
            <Route path="/about" element={<AboutPage />} />
            <Route path="*" element={<HomePage />} />
          </Routes>
        </main>
        <footer>
          <span>This product isn't affiliated with or endorsed by Grinding Gear Games in any way.</span>
          <span><Languages size={14} /> 繁中 / English</span>
        </footer>
      </div>
    </div>
  );
}

export const uiIcons = {
  BookOpen,
  Download,
  Flame,
  Search,
  ShieldCheck,
  ShoppingCart,
  Swords
};
