export function stageForLevel(level: number) {
  return rfChieftainGuide.stages.find((stage) =>
    level >= stage.levelRange[0] && level <= stage.levelRange[1]
  ) ?? (level > 100 ? rfChieftainGuide.stages.at(-1)! : rfChieftainGuide.stages[0]!);
}
