import {
  bridgeHealthSchema,
  buildSnapshotSchema,
  calculationResultSchema,
  comparisonReportSchema,
  type BuildSnapshot,
  type CalculationResult,
  type ComparisonReport,
  type ComparisonScenario
} from "@poe-odyssey/core";

const SESSION_KEY = "poe-odyssey-bridge";
const DEFAULT_PORT = 29129;

type BridgePairing = { port: number; token: string };

function pairingFromHash(): BridgePairing | null {
  const queryIndex = window.location.hash.indexOf("?");
  if (queryIndex < 0) return null;
  const params = new URLSearchParams(window.location.hash.slice(queryIndex + 1));
  const token = params.get("bridgeToken");
  const port = Number(params.get("bridgePort") ?? DEFAULT_PORT);
  if (!token || !Number.isInteger(port) || port < 1024 || port > 65535) return null;
  return { token, port };
}

export function captureBridgePairing(): void {
  const pairing = pairingFromHash();
  if (pairing) sessionStorage.setItem(SESSION_KEY, JSON.stringify(pairing));
}

function pairing(): BridgePairing | null {
  try {
    const raw = sessionStorage.getItem(SESSION_KEY);
    return raw ? JSON.parse(raw) as BridgePairing : null;
  } catch {
    return null;
  }
}

async function bridgeFetch(path: string, init?: RequestInit): Promise<unknown> {
  const pair = pairing();
  if (!pair) throw new Error("尚未與 PoeOdyssey Bridge 配對。");
  const response = await fetch(`http://127.0.0.1:${pair.port}${path}`, {
    ...init,
    headers: {
      Authorization: `Bearer ${pair.token}`,
      "Content-Type": "application/json",
      ...(init?.headers ?? {})
    }
  });
  const value = await response.json().catch(() => ({})) as { error?: string };
  if (!response.ok) throw new Error(value.error ?? `Bridge 回應 ${response.status}`);
  return value;
}

export async function bridgeHealth() {
  return bridgeHealthSchema.parse(await bridgeFetch("/v1/health"));
}

export async function bridgeDecode(input: string, name?: string): Promise<BuildSnapshot> {
  const value = await bridgeFetch("/v1/pob/decode", {
    method: "POST",
    body: JSON.stringify({ input, ...(name ? { name } : {}) })
  });
  return buildSnapshotSchema.parse(value);
}

export async function bridgeCalculate(input: string, scenario: ComparisonScenario): Promise<CalculationResult> {
  return calculationResultSchema.parse(await bridgeFetch("/v1/pob/calculate", {
    method: "POST",
    body: JSON.stringify({ input, scenario })
  }));
}

export async function bridgeCompare(
  source: BuildSnapshot,
  target: BuildSnapshot,
  scenario: ComparisonScenario,
  stageId: string
): Promise<BridgeComparison> {
  const value = await bridgeFetch("/v1/pob/compare", {
    method: "POST",
    body: JSON.stringify({ source, target, scenario, stageId })
  }) as Record<string, unknown>;
  const report = comparisonReportSchema.parse(value);
  const calculationsValue = value.calculations as Record<string, unknown> | undefined;
  const calculations = calculationsValue ? {
    source: calculationResultSchema.parse(calculationsValue.source),
    target: calculationResultSchema.parse(calculationsValue.target)
  } : undefined;
  const slotEffects = Array.isArray(value.slotEffects)
    ? value.slotEffects.filter((effect): effect is SlotEffect =>
      Boolean(effect) && typeof effect === "object" && typeof (effect as SlotEffect).slot === "string"
    )
    : undefined;
  return {
    ...report,
    ...(calculations ? { calculations } : {}),
    ...(slotEffects ? { slotEffects } : {})
  };
}

export interface SlotEffect {
  slot: string;
  item: string;
  damageDelta: number | null;
  survivalDelta: number | null;
}

export type BridgeComparison = ComparisonReport & {
  calculations?: {
    source: CalculationResult;
    target: CalculationResult;
  };
  slotEffects?: SlotEffect[];
};
