import { AlertTriangle, Check, ExternalLink, FlaskConical, Gem, Shield, Sparkles, Swords, Target } from "lucide-react";
import { useMemo, useState } from "react";
import Overview from "../../content/guides/rf-chieftain/overview.mdx";
import { PageTitle } from "../App";
import { rfChieftainGuide } from "../content/rfChieftain";

const bilingual = (value: { zhTW: string; en: string }) => <>{value.zhTW}<small>{value.en}</small></>;

export function GuidePage() {
  const [stageId, setStageId] = useState(rfChieftainGuide.stages[0]!.id);
  const stage = useMemo(
    () => rfChieftainGuide.stages.find((item) => item.id === stageId) ?? rfChieftainGuide.stages[0]!,
    [stageId]
  );

  return (
    <div className="page guide-page">
      <PageTitle
        eyebrow={`${rfChieftainGuide.version} · ${rfChieftainGuide.ascendancy.en}`}
        title={rfChieftainGuide.title.zhTW}
        description={`${rfChieftainGuide.mainSkill.en} · 更新 ${rfChieftainGuide.updatedAt} · 依 Pohx 最新階段整理`}
      >
        <a className="button secondary" href={rfChieftainGuide.sources[0]!.url} target="_blank" rel="noreferrer">
          原始指南 <ExternalLink size={15} />
        </a>
      </PageTitle>

      <section className="guide-overview">
        <div className="mdx-content"><Overview /></div>
        <div className="scenario-card">
          <span className="eyebrow">NORMALIZED POB</span>
          <h3>{rfChieftainGuide.scenario.name.zhTW}</h3>
          <dl>
            <div><dt>Boss</dt><dd>Pinnacle</dd></div>
            <div><dt>藥劑</dt><dd>關閉 / Off</dd></div>
            <div><dt>敵人移動</dt><dd>否 / No</dd></div>
          </dl>
          <p>升級比較固定使用此設定，原作者數值仍分開保留。</p>
        </div>
      </section>

      <div className="stage-picker" aria-label="攻略階段">
        {rfChieftainGuide.stages.map((item, index) => (
          <button
            key={item.id}
            className={item.id === stage.id ? "active" : ""}
            onClick={() => setStageId(item.id)}
          >
            <span>{String(index + 1).padStart(2, "0")}</span>
            <strong>{item.label.zhTW}</strong>
            <small>{item.label.en}</small>
          </button>
        ))}
      </div>

      <section className="stage-heading">
        <div>
          <span className="level-badge">LV {stage.levelRange[0]}–{stage.levelRange[1]}</span>
          <h2>{stage.headline.zhTW}</h2>
          <p className="english-title">{stage.headline.en}</p>
          <p>{stage.summary.zhTW}</p>
        </div>
        <div className="acts">{stage.acts.map((act) => <span key={act}>{act}</span>)}</div>
      </section>

      {stage.warnings.length > 0 && (
        <div className="warning-banner">
          <AlertTriangle size={19} />
          <div>{stage.warnings.map((warning) => <p key={warning.en}>{bilingual(warning)}</p>)}</div>
        </div>
      )}

      <div className="guide-grid">
        <section className="panel span-2">
          <div className="panel-title"><Target size={19} /><div><h3>現在要做什麼</h3><small>NEXT ACTIONS</small></div></div>
          <ol className="task-list">
            {stage.tasks.map((task, index) => (
              <li key={task.en}><span>{String(index + 1).padStart(2, "0")}</span><div>{bilingual(task)}</div></li>
            ))}
          </ol>
          {stage.ascendancy.length > 0 && (
            <div className="ascendancy-line"><Sparkles size={17} /><strong>昇華：</strong>{stage.ascendancy.map((item) => item.zhTW).join(" → ")}</div>
          )}
        </section>

        <section className="panel">
          <div className="panel-title"><Check size={19} /><div><h3>離開本階段前</h3><small>CHECKPOINT</small></div></div>
          <ul className="check-list">{stage.checklist.map((item) => <li key={item.en}><Check size={15} /><div>{bilingual(item)}</div></li>)}</ul>
        </section>

        <section className="panel span-2">
          <div className="panel-title"><Gem size={19} /><div><h3>技能連線</h3><small>SKILL LINKS</small></div></div>
          <div className="skill-groups">
            {stage.skills.map((group) => (
              <article key={group.label.en}>
                <header><div><strong>{group.label.zhTW}</strong><small>{group.label.en}</small></div>{group.socketHint && <code>{group.socketHint}</code>}</header>
                <div className="gem-chain">
                  {group.gems.map((item, index) => (
                    <div key={`${group.label.en}-${item.name.en}`} className={item.support ? "support-gem" : "active-gem"}>
                      {index > 0 && <span className="link-line" />}
                      <i>{item.support ? "S" : "G"}</i>
                      <span>{item.name.zhTW}<small>{item.name.en}</small></span>
                    </div>
                  ))}
                </div>
              </article>
            ))}
          </div>
        </section>

        <section className="panel">
          <div className="panel-title"><Shield size={19} /><div><h3>裝備優先</h3><small>GEAR</small></div></div>
          <div className="gear-list">
            {stage.gear.map((item) => (
              <article key={item.slot.en}>
                <div><strong>{item.slot.zhTW}</strong><small>{item.slot.en}</small>{item.required && <em>必要</em>}</div>
                <ul>{item.priorities.map((priority) => <li key={priority.en}>{bilingual(priority)}</li>)}</ul>
              </article>
            ))}
          </div>
        </section>

        <section className="panel">
          <div className="panel-title"><FlaskConical size={19} /><div><h3>藥水</h3><small>FLASKS</small></div></div>
          <div className="flask-list">{stage.flasks.map((item) => (
            <div key={item.name.en}><span className="flask-shape" /><p><strong>{item.name.zhTW}</strong><small>{item.name.en}</small>{item.note.zhTW}</p></div>
          ))}</div>
        </section>

        <section className="panel">
          <div className="panel-title"><Swords size={19} /><div><h3>天賦方向</h3><small>PASSIVES</small></div></div>
          <p className="passive-summary">{stage.passives.summary.zhTW}<small>{stage.passives.summary.en}</small></p>
          {stage.passives.keystones.length > 0 && <div className="keystones">{stage.passives.keystones.map((item) => <span key={item.en}>{bilingual(item)}</span>)}</div>}
        </section>
      </div>

      <section className="pob-targets">
        <div><span className="eyebrow">STAGE TARGETS</span><h3>PoB 檢查基準</h3></div>
        {Object.entries(stage.pobTargets).map(([key, value]) => (
          <div key={key}><small>{key}</small><strong>{value.toLocaleString()}</strong></div>
        ))}
      </section>
    </div>
  );
}
