import { AlertTriangle, Copy, ExternalLink, Search, ShieldCheck } from "lucide-react";
import { useMemo, useState } from "react";
import { createTradePayload, officialTradeUrl, type TradeSearch } from "@poe-odyssey/core";
import { PageTitle } from "../App";

const templates: Array<{ label: string; search: TradeSearch }> = [
  {
    label: "傳承憤怒 / Legacy of Fury",
    search: { league: "Allflame", name: "Legacy of Fury", rarity: "unique", onlineOnly: true, stats: [] }
  },
  {
    label: "烈炎之袍 / Cloak of Flame",
    search: { league: "Allflame", name: "Cloak of Flame", rarity: "unique", onlineOnly: true, stats: [] }
  },
  {
    label: "RF 稀有單手武器",
    search: {
      league: "Allflame",
      type: "Sceptre",
      rarity: "rare",
      onlineOnly: true,
      stats: [
        { id: "explicit.stat_3917489142", min: 20, disabled: false },
        { id: "explicit.stat_2300185227", min: 15, disabled: false }
      ]
    }
  }
];

export function TradePage() {
  const [selected, setSelected] = useState(0);
  const [copied, setCopied] = useState(false);
  const template = templates[selected]!;
  const payload = useMemo(() => createTradePayload(template.search), [template]);
  const url = officialTradeUrl(template.search.league);

  return (
    <div className="page trade-page">
      <PageTitle
        eyebrow="TAIWAN REALM · SAFE FALLBACK"
        title="台服市集查詢"
        description="準備可檢查的查詢模型，最後一步由你在官方台服市集送出。"
      />
      <div className="policy-banner">
        <ShieldCheck size={20} />
        <div>
          <strong>不代理登入、不保存 Cookie、不自動密語</strong>
          <p>GGG 文件只支援公開列出的 API，未公開的站內交易端點不屬於保證介面。PoeOdyssey 遇到任何限制都回到官方頁面。</p>
        </div>
      </div>

      <section className="trade-layout">
        <div className="panel template-list">
          <div className="panel-title"><Search size={19} /><div><h3>RF 升級範本</h3><small>QUERY TEMPLATES</small></div></div>
          {templates.map((item, index) => (
            <button key={item.label} className={index === selected ? "active" : ""} onClick={() => setSelected(index)}>
              <span>{String(index + 1).padStart(2, "0")}</span>{item.label}
            </button>
          ))}
        </div>
        <div className="panel query-preview">
          <div className="query-heading">
            <div><span className="eyebrow">CURRENT QUERY</span><h2>{template.label}</h2></div>
            <span className="realm-badge">台服 · Allflame</span>
          </div>
          <div className="query-facts">
            <div><small>稀有度</small><strong>{template.search.rarity}</strong></div>
            <div><small>上線狀態</small><strong>{template.search.onlineOnly ? "Online" : "Any"}</strong></div>
            <div><small>詞綴條件</small><strong>{template.search.stats.length}</strong></div>
          </div>
          <pre>{JSON.stringify(payload, null, 2)}</pre>
          <div className="trade-actions">
            <button className="button secondary" onClick={async () => {
              await navigator.clipboard.writeText(JSON.stringify(payload, null, 2));
              setCopied(true);
              window.setTimeout(() => setCopied(false), 1600);
            }}><Copy size={16} /> {copied ? "已複製" : "複製查詢 JSON"}</button>
            <a className="button primary" href={url} target="_blank" rel="noreferrer">開啟台服官方市集 <ExternalLink size={16} /></a>
          </div>
          <div className="fallback-note"><AlertTriangle size={16} /> 官方頁開啟後請手動套用條件；這個步驟刻意不透過未公開 API 自動送出。</div>
        </div>
      </section>
    </div>
  );
}
