import { AlertTriangle, CheckCircle2, Download, ExternalLink, MonitorDown, ShieldCheck } from "lucide-react";
import { useEffect, useState } from "react";
import { PageTitle } from "../App";

interface DownloadManifest {
  version: string;
  status?: string;
  engine: { name: string; version: string; commit: string };
  artifacts: Array<{ name: string; sha256: string; url?: string }>;
  notice: string;
}

export function DownloadPage() {
  const [manifest, setManifest] = useState<DownloadManifest | null>(null);
  const [error, setError] = useState(false);
  useEffect(() => {
    void fetch(`${import.meta.env.BASE_URL}downloads/manifest.json`, { cache: "no-store" })
      .then((response) => {
        if (!response.ok) throw new Error("manifest unavailable");
        return response.json() as Promise<DownloadManifest>;
      })
      .then(setManifest)
      .catch(() => setError(true));
  }, []);

  return (
    <div className="page download-page">
      <PageTitle
        eyebrow="WINDOWS 10/11 · X64"
        title="PoeOdyssey Bridge"
        description="在你的電腦上執行完整 Path of Building 計算；網站仍然只是靜態 GitHub Pages。"
      />
      <section className="download-hero">
        <div className="download-mark"><MonitorDown size={44} /></div>
        <div>
          <span className="eyebrow">LOCAL COMPANION</span>
          <h2>完整 PoB 重算，只在本機完成。</h2>
          <p>Bridge 綁定 127.0.0.1，以一次性權杖配對；不開放區網、不要求遊戲帳密，也不保存 POESESSID。</p>
          {manifest?.artifacts.length ? (
            <div className="download-buttons">
              {manifest.artifacts.filter((artifact) => artifact.name.endsWith(".exe")).map((artifact) => (
                <a
                  className="button primary"
                  key={artifact.name}
                  href={artifact.url ?? `${import.meta.env.BASE_URL}downloads/${encodeURIComponent(artifact.name)}`}
                >
                  <Download size={17} /> {artifact.name.toLowerCase().includes("portable") ? "Portable 免安裝版" : "NSIS 安裝版"}
                </a>
              ))}
            </div>
          ) : (
            <div className="not-published"><AlertTriangle size={17} /> Windows 首版尚未發布；可先使用純網頁 PoB 解析。</div>
          )}
        </div>
      </section>

      <section className="download-grid">
        <article className="panel">
          <ShieldCheck size={21} />
          <h3>安全邊界</h3>
          <ul>
            <li>只接受 production 與 localhost Origin</li>
            <li>Bearer token、CORS 與 Private Network Access</li>
            <li>8 MB 輸入限制、30 秒 PoB 計算逾時</li>
            <li>不提供任意網址代理</li>
          </ul>
        </article>
        <article className="panel">
          <CheckCircle2 size={21} />
          <h3>鎖定計算引擎</h3>
          <dl>
            <div><dt>Engine</dt><dd>{manifest?.engine.name ?? "Path of Building Community"}</dd></div>
            <div><dt>Version</dt><dd>{manifest?.engine.version ?? "2.66.2"}</dd></div>
            <div><dt>Commit</dt><dd>{manifest?.engine.commit.slice(0, 12) ?? "e0cc037d8b26"}</dd></div>
          </dl>
        </article>
      </section>

      <div className="smartscreen-warning">
        <AlertTriangle size={20} />
        <div>
          <strong>Windows SmartScreen 提示</strong>
          <p>{manifest?.notice ?? "首版沒有商業程式碼簽章憑證，Windows 可能顯示未知發行者。請只從本網站或 GitHub Release 下載，並核對 SHA-256。"}</p>
        </div>
      </div>

      {manifest?.artifacts.length ? (
        <section className="panel checksum-list">
          <h3>SHA-256</h3>
          {manifest.artifacts.map((artifact) => <div key={artifact.name}><span>{artifact.name}</span><code>{artifact.sha256}</code></div>)}
        </section>
      ) : null}

      <a className="text-link release-link" href="https://github.com/ts03408751/PoeOdyssey/releases" target="_blank" rel="noreferrer">
        查看 GitHub Releases <ExternalLink size={15} />
      </a>
      {error && <p className="manifest-error">無法讀取下載 manifest，請改到 GitHub Releases。</p>}
    </div>
  );
}
